async function sbRest(path, opts){
  const cfg = await flourishConfig();
  if (!cfg || !cfg.supabase_url) throw new Error("Directory unavailable right now");
  const token = (typeof authToken === "function") ? await authToken() : "";
  const headers = Object.assign(
    { apikey: cfg.supabase_anon_key, "Content-Type": "application/json" },
    token ? { Authorization: "Bearer " + token } : {},
    (opts && opts.headers) || {}
  );
  // Reads get a shorter leash than writes: nobody should watch a spinner for twelve
  // seconds to be told the directory is unreachable.
  const isWrite = opts && opts.method && opts.method !== "GET";
  const r = await fetchWithTimeout(cfg.supabase_url + "/rest/v1" + path,
    Object.assign({}, opts, { headers }), isWrite ? 12000 : 7000);
  if (!r.ok) {
    const detail = await r.text().catch(() => "");
    throw new Error(r.status === 401 ? "Please sign in to see this"
                  : "Could not load (" + r.status + ")" + (detail ? " " + detail.slice(0,120) : ""));
  }
  return r.status === 204 ? null : r.json();
}
const sbRpc = (fn, args) => sbRest("/rpc/" + fn, { method:"POST", body: JSON.stringify(args || {}) });

