/* ── join / leave ───────────────────────────────────────────────── */
async function joinChurch(id){
  if (!(typeof isSignedIn === "function" && isSignedIn())) { signInSheet(); return; }
  try {
    // RLS only permits inserting your OWN row with role member/visitor, so a client
    // cannot promote itself to church_admin here
    await sbRest("/church_memberships", { method:"POST",
      headers:{ Prefer:"resolution=merge-duplicates,return=minimal" },
      body: JSON.stringify({ church_id:id, role:"member", is_primary:true }) });
    await loadMembership(true);
    if (typeof earn === "function") earn("connector");
    toast("⛪ Welcome — you're in");
    S.route = {}; render();
  } catch (e) { toast("⚠ " + e.message); }
}
async function leaveChurch(id){
  if (!confirm("Leave this church? Your reading progress is unaffected.")) return;
  try {
    await sbRest("/church_memberships?church_id=eq." + encodeURIComponent(id),
                 { method:"DELETE", headers:{ Prefer:"return=minimal" } });
    await loadMembership(true);
    toast("You've left this church");
    S.route = {}; render();
  } catch (e) { toast("⚠ " + e.message); }
}
async function requestClaim(id){
  if (!(typeof isSignedIn === "function" && isSignedIn())) { signInSheet(); return; }
  try {
    const res = await sbRpc("claim_church", { p_church_id: id });
    if (res && res.ok === false) {
      toast(res.reason === "already_claimed" ? "This church already has an administrator"
                                             : "That church could not be found");
      return;
    }
    sheet(res && res.status === "approved"
      ? `<div class="center"><div class="e-ic" style="font-size:48px">✅</div>
         <h3 class="serif" style="font-size:20px">You're the administrator</h3>
         <p class="muted" style="margin:10px 0 16px">Your sign-in address matched the one on
         this church's record, so we could verify it straight away.</p>
         <button class="btn gold block" data-act="close-render">Open the dashboard</button></div>`
      : `<div class="center"><div class="e-ic" style="font-size:48px">📨</div>
         <h3 class="serif" style="font-size:20px">Claim submitted</h3>
         <p class="muted" style="margin:10px 0 16px">We review claims by hand so nobody can take
         over a congregation they don't lead. We'll email you once it's approved.</p>
         <button class="btn block" data-act="close-sheet">Got it</button></div>`);
  } catch (e) { toast("⚠ " + e.message); }
}

